import{I as t,o as p,c as o,b6 as e,J as r,w as d,j as i,a as l}from"./chunks/framework.COUcLbTA.js";const g=JSON.parse('{"title":"Double Diamond: 올바른 일을 먼저 하고, 그 일을 제대로 하기","description":"제로 베이스 독자를 위한 Double Diamond 입문 글입니다. Discover, Define, Develop, Deliver 네 단계를 이해하고, 문제가 명확해지기 전에 서둘러 프로토타입을 만드는 일을 피합니다.","frontmatter":{"title":"Double Diamond: 올바른 일을 먼저 하고, 그 일을 제대로 하기","description":"제로 베이스 독자를 위한 Double Diamond 입문 글입니다. Discover, Define, Develop, Deliver 네 단계를 이해하고, 문제가 명확해지기 전에 서둘러 프로토타입을 만드는 일을 피합니다."},"headers":[],"relativePath":"ko-kr/stage-1/appendix-double-diamond/index.md","filePath":"ko-kr/stage-1/appendix-double-diamond/index.md"}'),h={name:"ko-kr/stage-1/appendix-double-diamond/index.md"},D=Object.assign(h,{setup(c){const s="약 <strong>1.5시간</strong>";return(u,a)=>{const n=t("ChapterIntroduction");return p(),o("div",null,[a[1]||(a[1]=e('<h1 id="double-diamond-올바른-일을-먼저-하고-그-일을-제대로-하기" tabindex="-1">Double Diamond: 올바른 일을 먼저 하고, 그 일을 제대로 하기 <a class="header-anchor" href="#double-diamond-올바른-일을-먼저-하고-그-일을-제대로-하기" aria-label="Permalink to “Double Diamond: 올바른 일을 먼저 하고, 그 일을 제대로 하기”">​</a></h1><p><a id="top-dd"></a></p><h2 id="본-장-안내" tabindex="-1">본 장 안내 <a class="header-anchor" href="#본-장-안내" aria-label="Permalink to “본 장 안내”">​</a></h2>',3)),r(n,{duration:s,tags:["Double Diamond","디자인 사고","요구사항 분석","솔루션 설계"],coreOutput:"더 명확한 문제 정의 1개와 더 합리적인 검증 진입점 1개",expectedOutput:"처음부터 서둘러 프로토타입을 그리지 않고, 먼저 문제를 명확히 생각한 뒤 솔루션을 비교할 수 있게 됨"},{default:d(()=>[...a[0]||(a[0]=[i("p",null,'많은 사람이 처음 제품을 만들 때 가장 쉽게 빠지는 함정은 "노력이 부족하다"가 아니라 너무 빨리 해결책으로 들어가는 것입니다.',-1),i("p",null,"머릿속에 방향이 하나 떠오르자마자 페이지를 어떻게 그릴지, 버튼을 어디에 둘지, AI를 붙일지, 로그인/회원가입을 만들지, 어떤 도구로 프로토타입을 그릴지 생각하기 시작합니다. 한참 바쁘게 움직인 뒤에야 가장 근본적인 문제가 전혀 정리되지 않았다는 것을 깨닫습니다. 사용자가 정말 이 고통을 가지고 있는가? 지금 이 문제를 해결할 가치가 있는가? 프로젝트를 밀고 있다고 생각하지만, 사실은 잘못된 방향으로 열심히 가속하고 있을 뿐입니다.",-1),i("p",null,"Double Diamond 모델은 바로 이런 상황을 피하기 위해 쓰입니다.",-1),i("p",null,[l("가장 가치 있는 알림은 이것입니다. "),i("strong",null,'"올바른 일을 하는 것"과 "그 일을 제대로 하는 것"은 완전히 다른 두 단계입니다.'),l(" 문제가 명확해지기도 전에 프로토타입으로 달려가면, 보통 잘못된 방향을 더 완전하게 만들 뿐입니다.")],-1)])]),_:1}),a[2]||(a[2]=e(`<div class="info custom-block"><p class="custom-block-title">최소 SOP</p><p><strong>목적</strong>: 읽고 나면 제품을 만들 때 언제 먼저 문제를 생각해야 하고, 언제부터 솔루션과 프로토타입을 생각해야 하는지 더 명확해집니다. 처음부터 잘못된 방향을 매우 성실하게 만드는 일을 피합니다.</p><p><strong>행동 항목</strong>: <code>Discover → Define → Develop → Deliver</code> 네 단계를 따라 내려가며, 각 단계에서는 현재 단계에서 해야 할 일만 합니다.</p><p><strong>결과</strong>: 더 명확한 문제 정의, 비교 가능한 몇 가지 솔루션, 검증 가능한 최소 버전을 얻게 됩니다.</p><p><strong>키워드 이동</strong>: <a href="#dd-what">Double Diamond란 무엇인가</a> · <a href="#dd-first">첫 번째 다이아몬드</a> · <a href="#dd-ai">AI는 어떻게 도와줄 수 있나</a></p></div><h2 id="다음-내용을-배우게-됩니다" tabindex="-1">다음 내용을 배우게 됩니다 <a class="header-anchor" href="#다음-내용을-배우게-됩니다" aria-label="Permalink to “다음 내용을 배우게 됩니다”">​</a></h2><ol><li>Double Diamond가 무엇이고, 제로 베이스로 제품을 만들 때 왜 적합한지</li><li>Discover, Define, Develop, Deliver 네 단계가 각각 무엇을 하는지</li><li>&quot;지금은 계속 발산해야 하는가&quot;와 &quot;지금은 수렴을 시작해야 하는가&quot;를 구분하는 법</li><li>Double Diamond를 AI 제품, 프로토타입 설계, 요구사항 검증에 적용하는 법</li></ol><p><a id="dd-what"></a></p><h2 id="_1-double-diamond란-정확히-무엇인가" tabindex="-1"><a href="#top-dd">1. Double Diamond란 정확히 무엇인가</a> <a class="header-anchor" href="#_1-double-diamond란-정확히-무엇인가" aria-label="Permalink to “1. Double Diamond란 정확히 무엇인가”">​</a></h2><p>Double Diamond는 영국 <strong>Design Council</strong>이 널리 알린 고전적인 디자인 프로세스 프레임워크입니다. 하나의 완전한 디자인과 혁신 과정을 연속된 두 개의 다이아몬드 모양으로 그립니다.</p><p>&quot;다이아몬드&quot;인 이유는 각 다이아몬드가 서로 반대지만 모두 중요한 두 가지 동작을 포함하기 때문입니다.</p><ul><li><strong>발산</strong>: 먼저 시야를 열고 더 많은 가능성을 본다.</li><li><strong>수렴</strong>: 다시 범위를 좁혀 판단하고 취사선택한다.</li></ul><p>전체 과정은 네 단계입니다.</p><ol><li><strong>Discover</strong>: 사용자, 문제, 환경, 시장을 넓게 이해한다.</li><li><strong>Define</strong>: 많은 정보 속에서 진짜 해결할 가치가 있는 핵심 문제를 추출한다.</li><li><strong>Develop</strong>: 핵심 문제를 둘러싸고 여러 해결책을 발산한다.</li><li><strong>Deliver</strong>: 더 적합한 해결책을 선별하고, 프로토타입을 만들고, 테스트하고 전달한다.</li></ol><p>이 네 단계를 가장 기억하기 쉬운 한 문장으로 압축하면 이렇습니다.</p><ul><li><strong>첫 번째 다이아몬드</strong>: 정확히 어떤 문제를 해결해야 하는지 먼저 파악한다.</li><li><strong>두 번째 다이아몬드</strong>: 그다음 어떤 방법으로 해결할지 결정한다.</li></ul><p>이것이 방금 말한 아주 정확한 문장입니다.</p><ul><li><strong>첫 번째 다이아몬드: 올바른 일을 하기</strong></li><li><strong>두 번째 다이아몬드: 그 일을 제대로 하기</strong></li></ul><h2 id="_2-왜-double-diamond는-초보자에게-특히-적합한가" tabindex="-1">2. 왜 Double Diamond는 초보자에게 특히 적합한가 <a class="header-anchor" href="#_2-왜-double-diamond는-초보자에게-특히-적합한가" aria-label="Permalink to “2. 왜 Double Diamond는 초보자에게 특히 적합한가”">​</a></h2><p>초보자가 제품을 만들 때 가장 흔한 리듬은 보통 이렇습니다.</p><ul><li>아이디어가 떠오른다.</li><li>이 방향이 멋지다고 느낀다.</li><li>바로 프로토타입을 그리기 시작한다.</li><li>만들다 보니 기능이 점점 많아진다.</li><li>마지막에는 자신이 정확히 어떤 문제를 해결하는지 모르게 된다.</li></ul><p>Double Diamond의 가치는 프로세스를 복잡하게 만드는 데 있지 않습니다. <strong>&quot;문제 이해&quot;와 &quot;솔루션 설계&quot;를 강제로 분리하게 하는 데</strong> 있습니다.</p><p>이 말은 평범하게 들리지만 실제로는 매우 중요합니다. 실패한 제품의 상당수는 실행이 성실하지 않아서가 아니라 다음 이유 때문입니다.</p><ul><li>문제를 잘못 골랐다.</li><li>사용자를 오해했다.</li><li>해결책을 너무 일찍 고정했다.</li><li>방향 검증 없이 세부 다듬기에 많은 시간을 썼다.</li></ul><p>Double Diamond는 계속해서 이렇게 상기시킵니다.</p><ul><li>생각이 잘 이어진다고 해서 문제가 성립했다고 기본 가정하지 마세요.</li><li>해결책을 만들 수 있다고 해서 그것이 만들 가치가 있다고 기본 가정하지 마세요.</li><li>프로토타입이 완성되어 보인다고 해서 사용자가 정말 필요로 할 것이라고 기본 가정하지 마세요.</li></ul><p><a id="dd-first"></a></p><h2 id="_3-첫-번째-다이아몬드-올바른-일을-하기" tabindex="-1"><a href="#top-dd">3. 첫 번째 다이아몬드: 올바른 일을 하기</a> <a class="header-anchor" href="#_3-첫-번째-다이아몬드-올바른-일을-하기" aria-label="Permalink to “3. 첫 번째 다이아몬드: 올바른 일을 하기”">​</a></h2><p>첫 번째 다이아몬드는 <strong>문제 자체</strong>에 집중하며, 해결책에 집중하지 않습니다.</p><p>한 문장으로 이해하면 이렇습니다. <strong>서둘러 만들지 말고, 정말 만들 가치가 있는지 먼저 파악하세요.</strong></p><h3 id="_3-1-discover-먼저-문제-공간을-열기" tabindex="-1">3.1 Discover: 먼저 문제 공간을 열기 <a class="header-anchor" href="#_3-1-discover-먼저-문제-공간을-열기" aria-label="Permalink to “3.1 Discover: 먼저 문제 공간을 열기”">​</a></h3><p>Discover 단계의 핵심 과제는 <strong>넓게 조사하는 것</strong>이지, 빠르게 결론을 내리는 것이 아닙니다.</p><p>이 단계에서 보통 하는 일은 다음과 같습니다.</p><ul><li>사용자가 실제 장면에서 어떻게 행동하는지 보기</li><li>잠재 사용자를 인터뷰해 최근 언제 문제를 만났는지 이해하기</li><li>지금은 어떻게 임시로 해결하고 있는지 관찰하기</li><li>경쟁 제품과 대체 방안이 어떻게 처리하는지 보기</li><li>시장, 프로세스, 제약, 상하류 정보를 수집하기</li></ul><p>많은 사람이 Discover를 &quot;자료를 좀 더 많이 보는 것&quot;으로 오해합니다. 사실 더 중요한 것은 <strong>사람과 장면을 이해하는 것</strong>이지, 정보만 잔뜩 검색하는 것이 아닙니다.</p><p>예를 들어 &quot;AI가 회의록 정리를 도와주는 도구&quot;를 만들고 싶다면, Discover 단계에서 더 집중해야 할 것은 다음입니다.</p><ul><li>사용자가 회의 후 정확히 어느 부분에서 가장 고통스러워하는지</li><li>기록이 어려운지, 정리가 어려운지, 동기화가 어려운지</li><li>지금은 직접 쓰는지, 인턴에게 시키는지, 녹음을 다시 듣는지, 아예 정리하지 않는지</li><li>어떤 회의 장면에서 회의록이 가장 필요하고, 어떤 장면에서는 전혀 필요 없는지</li></ul><p>이 단계에서 가장 중요한 목표는 답을 내는 것이 아니라, <strong>너무 일찍 자신이 이미 답을 알고 있다고 착각하지 않는 것</strong>입니다.</p><h3 id="_3-2-define-많은-정보-속에서-핵심-문제-추출하기" tabindex="-1">3.2 Define: 많은 정보 속에서 핵심 문제 추출하기 <a class="header-anchor" href="#_3-2-define-많은-정보-속에서-핵심-문제-추출하기" aria-label="Permalink to “3.2 Define: 많은 정보 속에서 핵심 문제 추출하기”">​</a></h3><p>Discover가 시야를 여는 것이라면, Define은 수렴을 시작하는 것입니다.</p><p>Define 단계에서 해야 할 일은 모든 관찰을 그대로 보존하는 것이 아니라, 다음을 묻는 것입니다.</p><ul><li>진짜로 가장 우선 해결할 가치가 있는 문제는 무엇인가?</li><li>어떤 문제가 가장 자주 나타나고, 가장 아프고, 가장 가치 있는가?</li><li>첫 번째 버전은 정확히 어떤 장면 하나만 겨냥할 것인가?</li></ul><p>이 단계의 핵심은 넓은 주제를 명확한 문제 정의로 수렴하는 것입니다.</p><p>처음에는 이렇게 말할 수 있습니다.</p><blockquote><p>회의 효율을 높이는 AI 도구를 만들고 싶다.</p></blockquote><p>Define 단계에 이르면 더 좋은 표현은 이렇게 바뀔 수 있습니다.</p><blockquote><p>우리는 먼저 프로젝트형 팀이 30~60분짜리 협업 회의가 끝난 뒤, 10분 안에 할 일, 담당자, 마감일이 포함된 회의록을 만들지 못하는 문제를 해결한다.</p></blockquote><p>이제 문제가 명확해지기 시작합니다.</p><ul><li>사용자는 누구인가</li><li>장면은 무엇인가</li><li>막히는 지점은 무엇인가</li><li>성공 기준은 무엇인가</li></ul><p>Define의 본질은 <strong>&quot;문제가 많다&quot;에서 &quot;이번에는 어떤 문제 하나를 먼저 해결할 것인가&quot;로 수렴하는 것</strong>입니다.</p><h2 id="_4-두-번째-다이아몬드-그-일을-제대로-하기" tabindex="-1">4. 두 번째 다이아몬드: 그 일을 제대로 하기 <a class="header-anchor" href="#_4-두-번째-다이아몬드-그-일을-제대로-하기" aria-label="Permalink to “4. 두 번째 다이아몬드: 그 일을 제대로 하기”">​</a></h2><p>첫 번째 다이아몬드를 완료한 뒤에야 진정으로 두 번째 다이아몬드에 들어가기에 적합합니다. 이때 해결하려는 것은 더 이상 모호한 방향이 아니라 수렴된 구체적인 문제이기 때문입니다.</p><h3 id="_4-1-develop-핵심-문제를-중심으로-솔루션-발산하기" tabindex="-1">4.1 Develop: 핵심 문제를 중심으로 솔루션 발산하기 <a class="header-anchor" href="#_4-1-develop-핵심-문제를-중심으로-솔루션-발산하기" aria-label="Permalink to “4.1 Develop: 핵심 문제를 중심으로 솔루션 발산하기”">​</a></h3><p>Develop 단계의 핵심은 <strong>같은 문제를 중심으로 여러 가능한 솔루션을 탐색하는 것</strong>입니다.</p><p>주의할 점은 여기서의 발산은 Discover 단계와 다릅니다.</p><ul><li>Discover의 발산은 문제 공간을 탐색하는 것입니다.</li><li>Develop의 발산은 해결책 공간을 탐색하는 것입니다.</li></ul><p>회의록 예시를 계속 쓰면, Develop 단계에서는 다음을 생각할 수 있습니다.</p><ul><li>웹 도구를 만들 것인가, 회의 플러그인을 만들 것인가</li><li>녹음 업로드 후 처리할 것인가, 실시간 기록할 것인가</li><li>요약만 할 것인가, 할 일 추출에 집중할 것인가</li><li>개인 효율을 강조할 것인가, 팀 동기화를 강조할 것인가</li><li>사용자가 자유롭게 편집하게 할 것인가, 구조화된 템플릿을 바로 출력할 것인가</li></ul><p>이 단계는 브레인스토밍에 매우 적합하고, 팀과 함께 솔루션을 넓히기에도 좋습니다.</p><p>하지만 전제가 있습니다. <strong>모든 솔루션은 이미 정의된 같은 문제를 섬겨야 합니다.</strong><br> 문제가 명확히 정의되지 않았다면 Develop은 쉽게 다시 기능이 난무하는 상태가 됩니다.</p><h3 id="_4-2-deliver-솔루션-선택-프로토타입-테스트-전달" tabindex="-1">4.2 Deliver: 솔루션 선택, 프로토타입, 테스트, 전달 <a class="header-anchor" href="#_4-2-deliver-솔루션-선택-프로토타입-테스트-전달" aria-label="Permalink to “4.2 Deliver: 솔루션 선택, 프로토타입, 테스트, 전달”">​</a></h3><p>Deliver 단계는 두 번째 다이아몬드 안의 수렴 단계입니다.</p><p>이때 해야 할 일은 더 많이 상상하는 것이 아니라 판단을 시작하는 것입니다.</p><ul><li>어떤 솔루션이 현재 단계에 가장 적합한가</li><li>어떤 버전이 가장 작지만 가장 유용한가</li><li>어떤 기능은 반드시 먼저 해야 하고, 어떤 기능은 나중으로 미뤄도 되는가</li><li>어떻게 프로토타입을 만들고, 테스트하고, 작은 범위에서 검증할 것인가</li></ul><p>많은 사람이 Deliver를 &quot;출시&quot;와 같다고 생각합니다. 사실 더 정확한 뜻은 <strong>하나의 솔루션을 테스트 가능하고, 검증 가능하며, 반복 개선 가능한 것으로 바꾸는 것</strong>입니다.</p><p>그것은 다음일 수 있습니다.</p><ul><li>저충실도 흐름도 한 장</li><li>Figma 프로토타입</li><li>실행 가능한 MVP</li><li>소규모 사용자 테스트</li><li>실제 피드백 이후의 반복 개선 버전</li></ul><p>Deliver의 핵심은 &quot;완벽한 전달&quot;이 아니라 <strong>가능한 한 빨리 솔루션을 실제 환경에 넣어 검증하는 것</strong>입니다.</p><h2 id="_5-가장-기억하기-쉬운-대조표" tabindex="-1">5. 가장 기억하기 쉬운 대조표 <a class="header-anchor" href="#_5-가장-기억하기-쉬운-대조표" aria-label="Permalink to “5. 가장 기억하기 쉬운 대조표”">​</a></h2><p>네 단계를 자꾸 헷갈린다면 아래 버전을 그대로 기억하세요.</p><table tabindex="0"><thead><tr><th>단계</th><th>무엇을 하는가</th><th>키워드</th><th>흔한 산출물</th></tr></thead><tbody><tr><td>Discover</td><td>문제 이해</td><td>조사, 관찰, 인터뷰, 정보 수집</td><td>사용자 인사이트, 장면 메모, 문제 목록</td></tr><tr><td>Define</td><td>문제 정의</td><td>추출, 집중, 취사선택, 문제 다시 쓰기</td><td>문제 정의, 우선순위, MVP 진입점</td></tr><tr><td>Develop</td><td>솔루션 탐색</td><td>브레인스토밍, 비교, 공동 창작, 프로토타입 구상</td><td>솔루션 목록, 흐름 스케치, 프로토타입 방향</td></tr><tr><td>Deliver</td><td>솔루션 검증</td><td>프로토타입, 테스트, 반복 개선, 전달</td><td>프로토타입, 테스트 피드백, 최적화 버전</td></tr></tbody></table><p>더 압축하면 이렇습니다.</p><ul><li><strong>Discover / Define</strong>: &quot;올바른 일을 하기&quot;를 해결한다.</li><li><strong>Develop / Deliver</strong>: &quot;그 일을 제대로 하기&quot;를 해결한다.</li></ul><h2 id="_6-double-diamond의-가장-흔한-오해" tabindex="-1">6. Double Diamond의 가장 흔한 오해 <a class="header-anchor" href="#_6-double-diamond의-가장-흔한-오해" aria-label="Permalink to “6. Double Diamond의 가장 흔한 오해”">​</a></h2><h3 id="_6-1-discover도-하지-않고-바로-deliver하기" tabindex="-1">6.1 Discover도 하지 않고 바로 Deliver하기 <a class="header-anchor" href="#_6-1-discover도-하지-않고-바로-deliver하기" aria-label="Permalink to “6.1 Discover도 하지 않고 바로 Deliver하기”">​</a></h3><p>가장 흔한 경우입니다. 많은 사람이 아이디어가 생기자마자 프로토타입을 그리고, PRD를 쓰고, 모델을 붙이고, 페이지를 만듭니다.</p><p>문제는 당신이 성실하지 않다는 것이 아니라, 해결할 가치가 있는 문제인지 아직 확인하지 않았을 수 있다는 점입니다.</p><h3 id="_6-2-discover는-오래-하지만-끝내-define하지-않기" tabindex="-1">6.2 Discover는 오래 하지만 끝내 Define하지 않기 <a class="header-anchor" href="#_6-2-discover는-오래-하지만-끝내-define하지-않기" aria-label="Permalink to “6.2 Discover는 오래 하지만 끝내 Define하지 않기”">​</a></h3><p>또 다른 극단은 계속 조사하고, 계속 자료를 보고, 계속 인터뷰하지만 좀처럼 수렴하지 못하는 것입니다.</p><p>Double Diamond는 무한 발산을 하라는 뜻이 아닙니다. 발산 후에는 반드시 판단과 취사선택으로 들어가야 한다고 알려 주는 것입니다.</p><h3 id="_6-3-define-이후-몰래-문제를-바꾸기" tabindex="-1">6.3 Define 이후 몰래 문제를 바꾸기 <a class="header-anchor" href="#_6-3-define-이후-몰래-문제를-바꾸기" aria-label="Permalink to “6.3 Define 이후 몰래 문제를 바꾸기”">​</a></h3><p>많은 팀은 Develop 단계에서 어떤 솔루션이 더 쉽게 만들 수 있다는 이유로, 기존 솔루션에 맞도록 문제 정의를 거꾸로 수정합니다.</p><p>이것은 위험합니다. 문제를 해결하는 것이 아니라 자신이 선호하는 솔루션을 정당화하고 있을 수 있기 때문입니다.</p><h3 id="_6-4-deliver를-크고-완전한-출시-로-오해하기" tabindex="-1">6.4 Deliver를 &quot;크고 완전한 출시&quot;로 오해하기 <a class="header-anchor" href="#_6-4-deliver를-크고-완전한-출시-로-오해하기" aria-label="Permalink to “6.4 Deliver를 &quot;크고 완전한 출시&quot;로 오해하기”">​</a></h3><p>Deliver는 완전한 제품을 모두 만들어야 끝난다는 뜻이 아닙니다. 많은 경우 테스트 가능한 프로토타입 하나, 실제 사용자 테스트 한 번이면 이미 좋은 deliver입니다.</p><h2 id="_7-ai-제품에서-double-diamond는-어떻게-쓰나" tabindex="-1">7. AI 제품에서 Double Diamond는 어떻게 쓰나 <a class="header-anchor" href="#_7-ai-제품에서-double-diamond는-어떻게-쓰나" aria-label="Permalink to “7. AI 제품에서 Double Diamond는 어떻게 쓰나”">​</a></h2><p>AI 제품은 특히 &quot;능력 우선&quot; 함정에 빠지기 쉽습니다. 모델 능력이 너무 매력적으로 보이기 때문입니다. 당신은 곧장 이런 생각을 하고 싶어질 수 있습니다.</p><ul><li>멀티모달을 붙일까</li><li>Agent를 만들까</li><li>워크플로우를 넣을까</li><li>음성, 이미지, 웹 검색을 연결할까</li></ul><p>하지만 Double Diamond는 먼저 이렇게 묻게 합니다.</p><ul><li>사용자는 정확히 어느 단계에서 정말 막혀 있는가</li><li>이 막힘은 반드시 AI가 있어야 해결되는가</li><li>AI를 쓰지 않는다면 기존 방법은 정확히 어디가 가장 나쁜가</li><li>AI가 들어간 뒤 가장 핵심적인 진전은 무엇인가</li></ul><p>이것은 흔한 상황을 피하게 해 줍니다. <strong>능력은 강한데 가치는 약한 상황</strong>입니다.</p><p>실용적인 순서는 다음과 같습니다.</p><ol><li>Discover 단계에서 사용자가 지금 어떻게 과제를 처리하는지 관찰한다.</li><li>Define 단계에서 가장 아픈 장면 하나를 명확한 문제 정의 한 문장으로 쓴다.</li><li>Develop 단계에서 어떤 AI 기능이 이 문제를 가장 잘 섬기는지 비교한다.</li><li>Deliver 단계에서 최소 버전을 만들고 실제 사용자에게 테스트하게 한다.</li></ol><h2 id="_8-바로-적용할-수-있는-double-diamond-템플릿" tabindex="-1">8. 바로 적용할 수 있는 Double Diamond 템플릿 <a class="header-anchor" href="#_8-바로-적용할-수-있는-double-diamond-템플릿" aria-label="Permalink to “8. 바로 적용할 수 있는 Double Diamond 템플릿”">​</a></h2><p>자기 제품을 만들고 있다면 이 순서대로 먼저 써 보세요.</p><h3 id="discover" tabindex="-1">Discover <a class="header-anchor" href="#discover" aria-label="Permalink to “Discover”">​</a></h3><ul><li>내가 관찰한 사용자는 누구인가?</li><li>그들이 최근 이 문제를 만난 것은 언제인가?</li><li>지금은 어떻게 해결하고 있는가?</li><li>가장 짜증 나고, 느리고, 불안한 지점은 무엇인가?</li></ul><h3 id="define" tabindex="-1">Define <a class="header-anchor" href="#define" aria-label="Permalink to “Define”">​</a></h3><ul><li>이 문제들 중 가장 우선 해결할 가치가 있는 것은 무엇인가?</li><li>어떤 장면이 가장 빈번하거나 가장 핵심적인가?</li><li>첫 번째 버전은 누구만, 무엇만 섬길 것인가?</li><li>성공적으로 해결되면 사용자의 상태는 어떻게 변하는가?</li></ul><h3 id="develop" tabindex="-1">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to “Develop”">​</a></h3><ul><li>이 문제에 대해 어떤 가능한 솔루션이 있는가?</li><li>어떤 솔루션이 가장 가볍고, 빠르고, 검증하기 쉬운가?</li><li>반드시 해야 할 것은 무엇이고, 나중으로 미룰 것은 무엇인가?</li></ul><h3 id="deliver" tabindex="-1">Deliver <a class="header-anchor" href="#deliver" aria-label="Permalink to “Deliver”">​</a></h3><ul><li>이 방향을 검증하기 위해 가장 작게 무엇을 전달할 수 있는가?</li><li>흐름도인가, 프로토타입인가, MVP인가?</li><li>누구에게 테스트해야 하는가?</li><li>테스트 후 계속할지, 수정할지, 포기할지는 어떻게 판단할 것인가?</li></ul><h2 id="_9-제로-베이스도-이해할-수-있는-예시" tabindex="-1">9. 제로 베이스도 이해할 수 있는 예시 <a class="header-anchor" href="#_9-제로-베이스도-이해할-수-있는-예시" aria-label="Permalink to “9. 제로 베이스도 이해할 수 있는 예시”">​</a></h2><p>&quot;대학생의 취업 이력서 준비를 돕는 AI 도구&quot;를 만들고 싶다고 가정해 봅시다.</p><p>많은 사람은 처음부터 두 번째 다이아몬드로 들어가 이런 생각을 시작합니다.</p><ul><li>원클릭 미화를 넣을까</li><li>지능형 문장 개선을 넣을까</li><li>JD 자동 매칭을 할까</li><li>자기소개서를 생성할까</li></ul><p>하지만 Double Diamond를 따르면 더 좋은 과정은 이렇습니다.</p><h3 id="첫-번째-다이아몬드" tabindex="-1">첫 번째 다이아몬드 <a class="header-anchor" href="#첫-번째-다이아몬드" aria-label="Permalink to “첫 번째 다이아몬드”">​</a></h3><p><strong>Discover</strong></p><ul><li>취업 준비생에게 최근 이력서를 고친 것이 언제인지 묻는다.</li><li>그들이 이전 이력서를 어떻게 새 버전으로 바꾸는지 본다.</li><li>가장 어려운 것이 &quot;쓸 줄 모름&quot;인지, &quot;고칠 줄 모름&quot;인지, &quot;좋은지 판단할 줄 모름&quot;인지 이해한다.</li></ul><p><strong>Define</strong></p><ul><li>마지막에는 더 구체적인 문제로 수렴한다.</li><li>&quot;대학생은 이력서를 만들 줄 모른다&quot;가 아니다.</li><li>&quot;처음 인턴십에 지원하는 학생은 기존 경험을 직무에 맞는 표현으로 바꾸기 어려워 지원을 미룬다&quot;이다.</li></ul><h3 id="두-번째-다이아몬드" tabindex="-1">두 번째 다이아몬드 <a class="header-anchor" href="#두-번째-다이아몬드" aria-label="Permalink to “두 번째 다이아몬드”">​</a></h3><p><strong>Develop</strong></p><ul><li>몇 가지 솔루션을 생각한다. 템플릿 라이브러리, AI 문장 개선, 직무 대조, 이력서 점수화, 사례 참고.</li></ul><p><strong>Deliver</strong></p><ul><li>첫 버전은 &quot;직무 설명에 따라 경험 bullet point를 바꿔 쓰기&quot;만 만든다.</li><li>학생 5명에게 써 보게 하고, 더 빨리 첫 버전의 이력서를 제출하게 되는지 본다.</li></ul><p>첫 번째 다이아몬드를 탄탄하게 하면 두 번째 다이아몬드가 훨씬 명확해진다는 것을 알 수 있습니다.</p><h2 id="_10-정리" tabindex="-1">10. 정리 <a class="header-anchor" href="#_10-정리" aria-label="Permalink to “10. 정리”">​</a></h2><p>Double Diamond의 가장 강한 힘은 혼란스러운 덩어리를 네 개의 더 명확한 동작으로 나눠 준다는 데 있습니다.</p><ul><li>먼저 발산해 문제를 이해한다.</li><li>다시 수렴해 문제를 정의한다.</li><li>다시 발산해 솔루션을 탐색한다.</li><li>마지막으로 수렴해 솔루션을 전달한다.</li></ul><p>이 모델은 당신을 느리게 만들기 위한 것이 아닙니다. <strong>바빠 보이지만 사실 방향이 틀린 수많은 우회로를 줄이기 위한 것</strong>입니다.</p><p>특히 AI 시대에는 만드는 속도가 점점 빨라지기 때문에 Double Diamond가 오히려 더 중요해집니다. &quot;만드는 것&quot;이 점점 쉬워질수록 진짜 희소한 능력은 이렇게 바뀌기 때문입니다. <strong>해결할 가치가 있는 문제를 풀고 있는가, 그리고 그것을 적합한 방식으로 풀고 있는가.</strong></p><p>이 한 문장만 기억하면 됩니다.</p><p><strong>올바른 일을 먼저 하고, 그 일을 제대로 하세요.</strong></p><p><a id="dd-ai"></a></p><h2 id="_11-ai로-double-diamond-흐름을-실행하는-방법" tabindex="-1"><a href="#top-dd">11. AI로 Double Diamond 흐름을 실행하는 방법</a> <a class="header-anchor" href="#_11-ai로-double-diamond-흐름을-실행하는-방법" aria-label="Permalink to “11. AI로 Double Diamond 흐름을 실행하는 방법”">​</a></h2><p>Double Diamond 자체는 AI 도구가 아니지만, AI는 네 단계에서 &quot;가속기&quot; 역할을 하기에 매우 적합합니다. 핵심은 AI가 대신 결정하게 하는 것이 아니라, 시야 확장, 정보 정리, 솔루션 비교, 검증 자료 생성을 돕게 하는 것입니다.</p><h3 id="_11-1-discover-단계에서-ai로-정보-밑작업-한-번-하기" tabindex="-1">11.1 Discover 단계에서 AI로 정보 밑작업 한 번 하기 <a class="header-anchor" href="#_11-1-discover-단계에서-ai로-정보-밑작업-한-번-하기" aria-label="Permalink to “11.1 Discover 단계에서 AI로 정보 밑작업 한 번 하기”">​</a></h3><p>정식 인터뷰와 조사를 시작하기 전에 AI에게 가벼운 문제 스캔을 맡길 수 있습니다. 예를 들면 다음입니다.</p><ul><li>시장에서 흔한 대체 방안은 무엇인가</li><li>사용자가 공개 커뮤니티에서 가장 자주 불평하는 것은 무엇인가</li><li>이 문제는 어떤 장면과 사람군에서 자주 나타나는가</li><li>기존 제품은 보통 무엇을 놓치고 있는가</li></ul><p>이 단계는 실제 조사를 대체할 수 없지만, 문제 지도를 빠르게 만드는 데 매우 적합합니다.</p><p>아주 간단한 초보자 입력은 이렇게 쓸 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>대학생 이력서 수정을 도와주는 도구를 만들고 싶어.</span></span>
<span class="line"><span>기능을 생각해 주지 말고, 이 문제에서 사람들이 가장 자주 겪는 어려움이 무엇인지 먼저 봐 줘.</span></span></code></pre></div><p>AI는 이렇게 출력할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>초기 문제 지도:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 어떤 경험을 써야 할지 모름</span></span>
<span class="line"><span>2. 직무에 맞게 어떻게 수정해야 할지 모름</span></span>
<span class="line"><span>3. 여러 번 고쳤는데도 충분히 좋은지 확신하지 못함</span></span>
<span class="line"><span>4. 다른 사람에게 봐 달라고 해야 하지만 매번 부탁하기 불편함</span></span>
<span class="line"><span>5. 확신이 없어서 계속 지원을 미룸</span></span></code></pre></div><p>이 출력의 역할은 결론을 대신 내려 주는 것이 아니라, Discover에 더 빨리 들어가게 해 주는 것입니다.</p><h3 id="_11-2-define-단계에서-ai에게-문제-정의-수렴을-돕게-하기" tabindex="-1">11.2 Define 단계에서 AI에게 문제 정의 수렴을 돕게 하기 <a class="header-anchor" href="#_11-2-define-단계에서-ai에게-문제-정의-수렴을-돕게-하기" aria-label="Permalink to “11.2 Define 단계에서 AI에게 문제 정의 수렴을 돕게 하기”">​</a></h3><p>많은 사람이 자료를 한가득 모은 뒤 가장 어려워하는 것은 문제를 진짜 명확한 한 문장으로 줄이는 일입니다. 조사 메모를 AI에게 주고 몇 가지 후보 문제 정의로 압축하게 할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>아래는 Discover 단계에서 모은 사용자 피드백과 조사 메모야.</span></span>
<span class="line"><span>[내용 붙여넣기]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>다음 세 가지를 도와줘.</span></span>
<span class="line"><span>1. 가장 자주 나타나는 문제 패턴을 요약</span></span>
<span class="line"><span>2. 문제 빈도, 고통감, 검증 가능성을 기준으로 우선 해결할 가치가 있는 문제 3개 정리</span></span>
<span class="line"><span>3. 각 문제를 구체적인 문제 정의 한 문장으로 작성</span></span></code></pre></div><p>이렇게 하면 &quot;문제가 너무 많다&quot;에 머무르지 않고 Define으로 들어가기 쉬워집니다.</p><p>입력을 아주 간단하게 써도 됩니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>지금 모은 문제는 이거야.</span></span>
<span class="line"><span>1. 다들 이력서에 무엇을 써야 할지 모름</span></span>
<span class="line"><span>2. 다들 어떻게 고쳐야 할지 모름</span></span>
<span class="line"><span>3. 다들 잘 고친 건지 확신하지 못해 지원을 망설임</span></span>
<span class="line"><span></span></span>
<span class="line"><span>첫 버전에서 어떤 문제를 먼저 해결하는 게 가장 적합한지 봐 줘.</span></span></code></pre></div><p>AI는 이렇게 출력할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>우선 해결을 추천하는 문제:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;처음 인턴십에 지원하는 학생은 이력서가 이미 지원 가능한 수준인지 확신하지 못해 반복 수정하고 지원을 미룬다.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>이유:</span></span>
<span class="line"><span>1. 문제가 더 구체적이다.</span></span>
<span class="line"><span>2. 지연 행동을 설명할 수 있다.</span></span>
<span class="line"><span>3. 작은 버전을 설계해 검증하기 쉽다.</span></span></code></pre></div><p>이런 출력은 유용합니다. 흐릿한 문제들 속에서 MVP 출발점에 가까운 정의 하나를 수렴하게 해 주기 때문입니다.</p><h3 id="_11-3-develop-단계에서-ai로-여러-솔루션-발산하기" tabindex="-1">11.3 Develop 단계에서 AI로 여러 솔루션 발산하기 <a class="header-anchor" href="#_11-3-develop-단계에서-ai로-여러-솔루션-발산하기" aria-label="Permalink to “11.3 Develop 단계에서 AI로 여러 솔루션 발산하기”">​</a></h3><p>많은 사람은 문제를 정의하자마자 머릿속에 처음 떠오른 솔루션만 바라봅니다. 이 단계에서 AI는 강제로 발산시키는 데 매우 적합합니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>핵심 문제를 이렇게 정의했어: [문제 정의]</span></span>
<span class="line"><span>최종 답을 하나만 주지 말고, 아래 각도에서 2~3가지 해결 방향을 제안해 줘.</span></span>
<span class="line"><span>1. 가장 가벼운 MVP</span></span>
<span class="line"><span>2. 수요 검증에 가장 적합한 방안</span></span>
<span class="line"><span>3. 경험 개선에 가장 적합한 방안</span></span>
<span class="line"><span>4. AI에 의존하지 않는 방안</span></span>
<span class="line"><span>5. AI에 의존하는 방안</span></span>
<span class="line"><span>마지막에는 각 방안의 장점, 위험, 검증 비용을 비교해 줘.</span></span></code></pre></div><p>이렇게 하면 너무 일찍 하나의 솔루션에 묶이지 않게 됩니다.</p><p>간단한 입력은 이렇게 쓸 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>현재 문제 정의는 이거야.</span></span>
<span class="line"><span>&quot;대학생은 이력서가 이미 지원 가능한지 확신하지 못해 계속 미루고 있다.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>서로 다른 해결책 4가지를 생각해 줘. 하나만 주지 마.</span></span></code></pre></div><p>AI는 이렇게 출력할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>방안 1: 이력서 지원 가능 체크리스트</span></span>
<span class="line"><span>방안 2: 직무 설명에 맞춘 맞춤형 문장 개선</span></span>
<span class="line"><span>방안 3: 사용자가 이력서를 업로드하면 위험 알림 제공</span></span>
<span class="line"><span>방안 4: 우수 사례 대조를 제공해 사용자가 차이를 판단하도록 도움</span></span></code></pre></div><p>이때부터 &quot;솔루션 비교&quot;로 들어가기 쉬워지고, 처음부터 AI 문장 개선 하나만 바라보지 않게 됩니다.</p><h3 id="_11-4-deliver-단계에서-ai로-프로토타입-문구와-테스트-자료-생성하기" tabindex="-1">11.4 Deliver 단계에서 AI로 프로토타입 문구와 테스트 자료 생성하기 <a class="header-anchor" href="#_11-4-deliver-단계에서-ai로-프로토타입-문구와-테스트-자료-생성하기" aria-label="Permalink to “11.4 Deliver 단계에서 AI로 프로토타입 문구와 테스트 자료 생성하기”">​</a></h3><p>Deliver 단계에 들어가면 AI는 다음 작업을 빠르게 처리하는 데 매우 적합합니다.</p><ul><li>저충실도 프로토타입의 페이지 문구 생성</li><li>사용자 테스트 스크립트 정리</li><li>비교 가능한 여러 버전의 제목, 버튼, 설명문 생성</li><li>테스트 후 피드백과 문제 목록 정리</li></ul><p>예를 들어 AI에게 20분 사용자 테스트 스크립트를 만들게 하거나, 사용자 5명의 피드백을 &quot;계속 진행 / 방향 수정 / 중단&quot; 판단 근거로 정리하게 할 수 있습니다.</p><p>가장 작은 입력 예시는 다음입니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>아주 간단한 프로토타입을 만들었어.</span></span>
<span class="line"><span>사용자가 이력서를 업로드하면, 시스템이 어떤 부분이 아직 지원하기에 적합하지 않은지 알려 줘.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>15분짜리 사용자 테스트 스크립트를 만들어 줘.</span></span></code></pre></div><p>AI는 이렇게 출력할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>15분 테스트 스크립트:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 먼저 사용자에게 최근 이력서 지원 경험을 설명하게 한다.</span></span>
<span class="line"><span>2. 사용자가 독립적으로 이력서 업로드를 완료하게 한다.</span></span>
<span class="line"><span>3. 피드백 결과를 이해하는지 관찰한다.</span></span>
<span class="line"><span>4. 질문: 이 안내 중 어떤 것이 가장 도움이 되고, 어떤 것이 헷갈렸나요?</span></span>
<span class="line"><span>5. 질문: 다음 지원 전에 다시 쓰고 싶나요?</span></span></code></pre></div><p>이 출력은 실용적입니다. &quot;프로토타입을 만들었다&quot;에서 &quot;다음에는 어떻게 테스트할까&quot;로 넘어가게 해 주기 때문입니다.</p><h3 id="_11-5-ai에게-단계-문지기-역할을-맡기기" tabindex="-1">11.5 AI에게 &quot;단계 문지기&quot; 역할을 맡기기 <a class="header-anchor" href="#_11-5-ai에게-단계-문지기-역할을-맡기기" aria-label="Permalink to “11.5 AI에게 &quot;단계 문지기&quot; 역할을 맡기기”">​</a></h3><p>Double Diamond에서 가장 흔한 문제는 사람이 단계를 건너뛰는 것입니다. AI에게 직접 문지기 역할을 맡겨 현재 어느 단계에 있는지 알려 달라고 할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>제품 프로세스 코치 역할을 해 줘.</span></span>
<span class="line"><span>아래는 현재 내 프로젝트 상태야: [설명]</span></span>
<span class="line"><span>내가 지금 Discover, Define, Develop, Deliver 중 어디에 더 가까운지 판단해 줘.</span></span>
<span class="line"><span>그리고 알려 줘.</span></span>
<span class="line"><span>1. 내가 너무 일찍 다음 단계로 넘어갔는지</span></span>
<span class="line"><span>2. 현재 단계에서 가장 보충해야 할 행동은 무엇인지</span></span>
<span class="line"><span>3. 지금은 먼저 하지 말아야 할 일은 무엇인지</span></span></code></pre></div><p>초보자에게 특히 유용합니다. &quot;문제를 아직 명확히 생각하지 않았는데 프로토타입을 그리기 시작하는&quot; 일이 매우 쉽게 일어나기 때문입니다.</p><h2 id="📚-assignments" tabindex="-1">📚 Assignments <a class="header-anchor" href="#📚-assignments" aria-label="Permalink to “📚 Assignments”">​</a></h2><p>위 내용을 바탕으로 다음 과제를 완료하세요.</p><ol><li>최근 만들고 싶은 제품 아이디어 하나를 고르고, Discover, Define, Develop, Deliver 네 단계 초안을 작성하세요.</li><li>Define 단계에서 문제를 구체적인 한 문장으로 강제로 줄이세요.</li><li>Develop 단계에서 처음 떠오른 방법 하나만 바라보지 말고, 최소 3가지 다른 방안을 나열하세요.</li><li>Deliver 단계에서 일주일 안에 전달 가능한 최소 검증 버전을 작성하세요.</li></ol><h2 id="더-읽어-보기" tabindex="-1">더 읽어 보기 <a class="header-anchor" href="#더-읽어-보기" aria-label="Permalink to “더 읽어 보기”">​</a></h2><p>이 글은 주로 Design Council의 Double Diamond 공식 자료를 참고했습니다. 이어서 보기 좋습니다.</p><ul><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/" target="_blank" rel="noreferrer">Design Council: The Double Diamond</a></li><li><a href="https://www.designcouncil.org.uk/our-work/skills-learning/tools-frameworks/framework-for-innovation-design-councils-evolved-double-diamond/" target="_blank" rel="noreferrer">Design Council: Framework for Innovation</a></li><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/history-of-the-double-diamond/" target="_blank" rel="noreferrer">Design Council: History of the Double Diamond</a></li></ul>`,171))])}}});export{g as __pageData,D as default};
